var autoSaveInput = (typeof autoSave !== "undefined") ? autoSave : null;
if ((autoSaveInput === null || autoSaveInput === undefined) && typeof commit !== "undefined") {
  autoSaveInput = commit;
}
var autoSaveFlag = C8O.util.parseAutoSaveFlag(autoSaveInput, true);
var refreshInput = (typeof refresh !== "undefined") ? refresh : true;
var refreshFlag = C8O.util.toBoolean(refreshInput, true) === true;
var optimizeMutationsInput = (typeof optimizeMutations !== "undefined") ? optimizeMutations : false;
var optimizeMutationsFlag = C8O.util.toBoolean(optimizeMutationsInput, false) === true;
if (optimizeMutationsFlag) {
  autoSaveFlag = false;
  refreshFlag = false;
}

var renameResult = C8O.dbo.renameObject({ qname: qname, name: name, update: update });

var classNameText = renameResult.className ? String(renameResult.className) : "";
var qnameText = renameResult.qname ? String(renameResult.qname) : String(qname);
var newQNameText = renameResult.newQName ? String(renameResult.newQName) : qnameText;
var oldNameText = renameResult.oldName ? String(renameResult.oldName) : "";
var newNameText = renameResult.newName ? String(renameResult.newName) : (name ? String(name) : "");
var parentQNameText = renameResult.parentQName ? String(renameResult.parentQName) : "";
var updateModeText = renameResult.updateMode ? String(renameResult.updateMode) : (update ? String(update) : "UPDATE_NONE");
var projectNameText = renameResult.projectName ? String(renameResult.projectName) : "";
var updatedIdsList = Array.isArray(renameResult.updatedIds) ? renameResult.updatedIds : [];

renameInfo = renameResult;
renameErrors = Array.isArray(renameResult.errors) ? renameResult.errors : [];
renameAutoSave = autoSaveFlag;
renameProject = renameResult.project || null;
renameSaved = false;
renameSaveMessage = "";
renameAutoSaveApplied = autoSaveFlag;
renameRenamed = Boolean(renameResult.renamed);
renameDone = renameRenamed;
renameClassName = classNameText;
renameQName = qnameText;
renameNewQName = newQNameText;
renameOldName = oldNameText;
renameNewName = newNameText;
renameParentQName = parentQNameText;
renameUpdateMode = updateModeText;
renameUpdatedIds = updatedIdsList;
renameProjectName = projectNameText;
renameShouldRefresh = refreshFlag && renameRenamed && parentQNameText.length > 0;
renameSummaryRenamed = renameRenamed ? 1 : 0;
renameSummaryErrors = renameErrors.length;

var saveResult = C8O.dbo.saveProjectIfNeeded(renameProject, renameAutoSave, renameErrors);
var savedFlag = saveResult.saved === true;
renameSaved = savedFlag;
renameSaveMessage = saveResult.message || "";
renameAutoSaveApplied = renameAutoSave;
